package dev.pocketengine.features.local.project;
import dev.pocketengine.features.workspace.VersionedWorkspace;
import dev.pocketengine.features.local.NativeCommandExecutor;
import java.io.File;import java.nio.file.*;import java.util.*;import org.json.*;
/** One real same-checkout rename inside the original patch operation, never a shell/copy-delete alias. */
public final class ProjectFileMove {
 public static final String CONTRACT="pocketworld.exact-source-file-move.v1";
 private ProjectFileMove(){}
 public static boolean matches(JSONObject row){return CONTRACT.equals(row.optString("bytePatchContract"));}
 public static boolean any(JSONArray rows)throws Exception{for(int i=0;i<rows.length();i++)if(matches(rows.getJSONObject(i)))return true;return false;}
 private static Set<String> keys(JSONObject value){Set<String> out=new TreeSet<>();value.keys().forEachRemaining(out::add);return out;}
 private static String path(String value){String p=VersionedWorkspace.path(value);if(!ProjectSources.sourcePath(p))throw new SecurityException("重命名只支持同副本source路径，不含依赖/构建目录");return p;}
 private static int count(Object value)throws Exception{if(!(value instanceof Integer||value instanceof Long)||((Number)value).longValue()<0||((Number)value).longValue()>ProjectExactPatch.MAX_TEXT_BYTES)throw new SecurityException("重命名原件需256KiB内准确字节大小");return ((Number)value).intValue();}
 private static byte[] decode(JSONObject row,String key)throws Exception{String value=row.getString(key);if(value.length()>((ProjectExactPatch.MAX_TEXT_BYTES+2)/3)*4)throw new SecurityException("重命名字节超过原计划范围");byte[] bytes;try{bytes=Base64.getDecoder().decode(value);}catch(IllegalArgumentException bad){throw new SecurityException("重命名原件不是完整Base64",bad);}if(bytes.length>ProjectExactPatch.MAX_TEXT_BYTES||!Base64.getEncoder().encodeToString(bytes).equals(value))throw new SecurityException("重命名原件字节不是canonical完整正文");return bytes;}
 public static JSONArray prepare(JSONObject snapshot,JSONObject edit)throws Exception{
  if(!keys(edit).equals(Set.of("action","path","fromPath","expectedHash","expectedSourceHash"))||!"move".equals(edit.optString("action"))||!"absent".equals(edit.optString("expectedHash")))throw new IllegalArgumentException("move只接收同副本fromPath/path、源SHA和目标absent，不接收正文/覆盖/递归参数");String from=path(edit.getString("fromPath")),to=path(edit.getString("path"));Map<String,byte[]> files=ProjectSources.byteFiles(snapshot);if(from.equals(to)||!files.containsKey(from)||files.containsKey(to))throw new SecurityException("重命名需不同的既有源文件与不存在的目标");byte[] bytes=files.get(from);if(bytes.length>ProjectExactPatch.MAX_TEXT_BYTES)throw new IllegalArgumentException("此原重命名计划仅支持256KiB内原件，未截断");String sha=ProjectSources.sha256(bytes);if(!sha.equals(edit.getString("expectedSourceHash")))throw new SecurityException("重命名源SHA已变化");JSONObject move=new JSONObject().put("fromPath",from).put("toPath",to).put("sha256",sha).put("bytes",bytes.length);return new JSONArray().put(row(move,bytes,true)).put(row(move,bytes,false));
 }
 private static JSONObject row(JSONObject move,byte[] bytes,boolean source)throws Exception{
  String role=source?"source":"target",sha=move.getString("sha256");JSONObject change=new JSONObject().put("kind","move_"+role).put("fromPath",move.getString("fromPath")).put("toPath",move.getString("toPath")).put("sourceHash",sha).put("sourceBytes",bytes.length);
  return new JSONObject().put("path",move.getString(source?"fromPath":"toPath")).put("action",source?"delete":"create").put("encoding","base64").put("bytePatchContract",CONTRACT).put("moveRole",role).put("move",new JSONObject(move.toString())).put("expectedHash",source?sha:"absent").put("afterHash",source?"absent":sha).put("beforeContentBase64",source?Base64.getEncoder().encodeToString(bytes):"").put("contentBase64",source?"":Base64.getEncoder().encodeToString(bytes)).put("beforeBytes",source?bytes.length:0).put("afterBytes",source?0:bytes.length).put("changes",new JSONArray().put(change));
 }
 public static byte[][] bytes(JSONObject row)throws Exception{
  if(!matches(row)||!keys(row).equals(Set.of("path","action","encoding","bytePatchContract","moveRole","move","expectedHash","afterHash","beforeContentBase64","contentBase64","beforeBytes","afterBytes","changes"))||!"base64".equals(row.optString("encoding")))throw new SecurityException("重命名行类型或字段不明确");String role=row.getString("moveRole");boolean source=role.equals("source");if(!source&&!role.equals("target"))throw new SecurityException("重命名角色无效");JSONObject move=row.getJSONObject("move");if(!keys(move).equals(Set.of("fromPath","toPath","sha256","bytes")))throw new SecurityException("重命名身份不完整");String from=path(move.getString("fromPath")),to=path(move.getString("toPath"));if(from.equals(to)||!path(row.getString("path")).equals(source?from:to)||!(source?"delete":"create").equals(row.optString("action")))throw new SecurityException("重命名源/目标动作不同");byte[] before=decode(row,"beforeContentBase64"),after=decode(row,"contentBase64"),original=source?before:after;String sha=ProjectSources.sha256(original);if(!sha.equals(move.optString("sha256"))||count(move.get("bytes"))!=original.length||count(row.get("beforeBytes"))!=before.length||count(row.get("afterBytes"))!=after.length||(source?after:before).length!=0||!(source?sha:"absent").equals(row.optString("expectedHash"))||!(source?"absent":sha).equals(row.optString("afterHash")))throw new SecurityException("重命名完整字节/源SHA/动作不符");JSONArray changes=row.getJSONArray("changes");if(changes.length()!=1)throw new SecurityException("重命名需唯一准确变化");JSONObject c=changes.getJSONObject(0);if(!keys(c).equals(Set.of("kind","fromPath","toPath","sourceHash","sourceBytes"))||!("move_"+role).equals(c.optString("kind"))||!from.equals(c.optString("fromPath"))||!to.equals(c.optString("toPath"))||!sha.equals(c.optString("sourceHash"))||count(c.get("sourceBytes"))!=original.length)throw new SecurityException("重命名审阅与原字节不同");return new byte[][]{before,after};
 }
 public static JSONObject pair(JSONArray rows)throws Exception{if(rows.length()!=2||!matches(rows.getJSONObject(0))||!matches(rows.getJSONObject(1))||!"source".equals(rows.getJSONObject(0).optString("moveRole"))||!"target".equals(rows.getJSONObject(1).optString("moveRole")))throw new SecurityException("一次move须独占准确源/目标两行，不混其他修改");byte[][] source=bytes(rows.getJSONObject(0)),target=bytes(rows.getJSONObject(1));if(!ProjectSources.canonical(rows.getJSONObject(0).getJSONObject("move")).equals(ProjectSources.canonical(rows.getJSONObject(1).getJSONObject("move")))||!Arrays.equals(source[0],target[1]))throw new SecurityException("重命名源/目标不是同一原件");return rows.getJSONObject(0).getJSONObject("move");}
 public static void requireManifest(JSONObject plan,JSONObject step,JSONArray rows)throws Exception{JSONObject move=pair(rows);JSONObject payload=step.getJSONObject("payload");if(!Set.of("patch","revert_operation").contains(plan.optString("intent"))||!"patchFiles".equals(step.optString("localCommand"))||!plan.getString("checkoutId").equals(payload.optString("checkoutId"))||!plan.getString("sourceDigest").equals(payload.optString("expectedSourceDigest")))throw new SecurityException("重命名不在原精确补丁/撤销方案");boolean found=false;JSONArray manifest=plan.getJSONArray("sourceManifest");for(int i=0;i<manifest.length();i++){JSONObject f=manifest.getJSONObject(i);if(move.getString("toPath").equals(f.getString("path")))throw new SecurityException("重命名目标已在原source清单中");if(move.getString("fromPath").equals(f.getString("path"))){if(!move.getString("sha256").equals(f.getString("sha256"))||count(move.get("bytes"))!=f.getLong("bytes"))throw new SecurityException("重命名原件并非原source清单字节");found=true;}}if(!found)throw new SecurityException("重命名源不在固定source清单");}
 public static void preflight(File root,String checkout,JSONArray rows,ProjectBinaryImport.Current current)throws Exception{JSONObject move=pair(rows);String from=move.getString("fromPath"),to=move.getString("toPath");File source=NativeCommandExecutor.within(root,from),target=NativeCommandExecutor.within(root,to);if(!source.getAbsoluteFile().equals(source.getCanonicalFile())||!target.getAbsoluteFile().equals(target.getCanonicalFile()))throw new SecurityException("重命名路径不能包含链接");var actual=ProjectBinaryImport.read(root,checkout,from,current);var destination=ProjectBinaryImport.read(root,checkout,to,current);if(actual.deleted||!move.getString("sha256").equals(actual.sha256)||!destination.deleted||!Files.isDirectory(target.getParentFile().toPath(),LinkOption.NOFOLLOW_LINKS))throw new SecurityException("重命名需准确既有源SHA、absent目标及已有父目录");current.check();}
 public static JSONObject execute(File root,String checkout,JSONArray rows,ProjectBinaryImport.Current current)throws Exception{
  JSONObject move=pair(rows);JSONArray receipts=new JSONArray();for(int i=0;i<2;i++){JSONObject row=rows.getJSONObject(i);receipts.put(new JSONObject().put("path",row.getString("path")).put("action",row.getString("action")).put("beforeHash",row.getString("expectedHash")).put("afterHash",row.getString("afterHash")).put("state","pending").put("commitAttempted",false).put("operation","same_checkout_move").put("peerPath",move.getString(i==0?"toPath":"fromPath")));}boolean entered=false;
  try{preflight(root,checkout,rows,current);Path sourcePath=NativeCommandExecutor.within(root,move.getString("fromPath")).toPath(),targetPath=NativeCommandExecutor.within(root,move.getString("toPath")).toPath();current.check();entered=true;for(int i=0;i<2;i++)receipts.getJSONObject(i).put("commitAttempted",true);Files.move(sourcePath,targetPath);var source=ProjectBinaryImport.read(root,checkout,move.getString("fromPath"),()->{});var target=ProjectBinaryImport.read(root,checkout,move.getString("toPath"),()->{});if(!source.deleted||target.deleted||!move.getString("sha256").equals(target.sha256))throw new IllegalStateException("重命名后状态未收敛");receipts.getJSONObject(0).put("state","applied").put("actualAfterHash","absent");receipts.getJSONObject(1).put("state","applied").put("actualAfterHash",target.sha256);return new JSONObject().put("replayAllowed",false).put("status","completed").put("exitCode",0).put("receiptReceived",true).put("files",receipts).put("appliedFiles",2).put("allFilesApplied",true).put("partialEffects",false).put("fileCommitAttempted",true).put("crossFileAtomic",false).put("message","已调用一次不带REPLACE的Files.move并核对旧源不存在、目标原SHA相同；只改此工作副本，不动正式版本库。未宣称跨路径原子CAS/跨域能力。");}
  catch(Exception unknown){for(int i=0;i<2;i++)receipts.getJSONObject(i).put("state",entered?"unknown":i==0?"failed":"skipped");return new JSONObject().put("replayAllowed",false).put("status",entered?"unknown":"failed").put("exitCode",entered?JSONObject.NULL:1).put("receiptReceived",!entered).put("files",receipts).put("appliedFiles",0).put("allFilesApplied",false).put("partialEffects",entered?JSONObject.NULL:false).put("fileCommitAttempted",entered).put("crossFileAtomic",false).put("message",entered?"rename已进入但未取得完整两路径回执；保留原操作unknown，只核对，不自动重放或反向":"rename预检/授权未通过，未进入系统调用；核对源SHA、目标不存在、父目录及原权限后重新明确计划");}
 }
 public static JSONArray reverse(JSONObject snapshot,JSONArray original,JSONObject receipt,String operation)throws Exception{ProjectExactPatch.requireSettledReceipt(receipt);JSONObject move=pair(original);JSONArray actual=receipt.getJSONArray("files");if(actual.length()!=2)throw new SecurityException("原重命名回执不完整");for(int i=0;i<2;i++){JSONObject row=original.getJSONObject(i),seen=actual.getJSONObject(i);if(!row.getString("path").equals(seen.optString("path"))||!"applied".equals(seen.optString("state"))||!row.getString("afterHash").equals(seen.optString("actualAfterHash")))throw new SecurityException("原重命名须两路径确证applied，unknown不反向");}Map<String,byte[]> current=ProjectSources.byteFiles(snapshot);if(current.containsKey(move.getString("fromPath"))||!current.containsKey(move.getString("toPath"))||!move.getString("sha256").equals(ProjectSources.sha256(current.get(move.getString("toPath")))))throw new SecurityException("原重命名之后路径或afterSHA已变化，未覆盖新内容");ProjectBuildPlan.identity(operation);return prepare(snapshot,new JSONObject().put("action","move").put("fromPath",move.getString("toPath")).put("path",move.getString("fromPath")).put("expectedHash","absent").put("expectedSourceHash",move.getString("sha256")));}
}
